{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A grounded guide to whole-person care</title>
  <meta name="description" content="Practical integrative guidance blending evidence-informed methods and life-friendly rhythms. Book a consult to begin." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="page-home">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><use href="assets/img/pattern.svg#mark" /></svg>
      <div>
        <strong class="business">{{BUSINESS_NAME}}</strong>
        <div class="tag">A human-centered path to balanced living</div>
      </div>
    </div>
    <nav class="primary-nav" aria-label="Main navigation">
      <a href="index.html" class="active">Home</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Ailments</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">Our Story</a>
      <a href="book.html">Schedule</a>
      <a href="contact.html">Connect</a>
    </nav>
    <a class="cta small" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <div class="hero-inner">
        <h1>Gentle clarity for complex lives</h1>
        <p class="intro">We help you shape realistic, whole-person plans that fit the rhythms of your day. Together we review body, mind, routine, and environment — then craft manageable steps that respect your priorities.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
          <a class="btn ghost" href="about.html">Meet the team</a>
        </div>
      </div>
      <div class="hero-pattern" aria-hidden="true">
        <svg viewBox="0 0 600 400" preserveAspectRatio="none"><use href="assets/img/pattern.svg#tile" /></svg>
      </div>
    </section>

    <!-- Social proof -->
    <section class="social-proof">
      <h2>Practically minded — quietly transformational</h2>
      <p>Clients often report steadier energy, clearer priorities, and fewer decision hang-ups after a few tailored sessions. (We track outcomes, not promises.)</p>
      <ul class="testimonials">
        <li>
          <blockquote>"I finally have a simple morning rhythm that actually sticks."</blockquote>
          <cite>— L., teacher, {{CITY}}</cite>
        </li>
        <li>
          <blockquote>"We mapped nutrition, sleep, and work rhythms in a way that felt doable."</blockquote>
          <cite>— M., designer</cite>
        </li>
        <li>
          <blockquote>"Care that listens, then offers clear steps."</blockquote>
          <cite>— R., parent</cite>
        </li>
      </ul>
    </section>

    <!-- Benefits -->
    <section class="benefits">
      <h2>What we help with</h2>
      <div class="cards">
        <div class="card"><h3>Energy & sleep rhythms</h3><p>Personalized routines to support restorative sleep and steady daytime focus.</p></div>
        <div class="card"><h3>Stress resilience</h3><p>Tools to shift your nervous system response and connect action with calm.</p></div>
        <div class="card"><h3>Movement that fits</h3><p>Short, progressive approaches to keep you strong and pain-aware.</p></div>
        <div class="card"><h3>Nutrition that suits your life</h3><p>Practical adjustments rather than rigid diets — food guidance aligned with preferences and routines.</p></div>
      </div>
    </section>

    <!-- Process (simplified) -->
    <section class="process">
      <h2>How a first month looks</h2>
      <ol>
        <li><strong>Listen:</strong> A comprehensive intake to map your priorities and concerns.</li>
        <li><strong>Plan:</strong> A focused agenda and weekly micro-goals designed to be sustainable.</li>
        <li><strong>Adjust:</strong> Regular check-ins to refine practices and cadence.</li>
      </ol>
    </section>

    <!-- Session Planner (interactive) -->
    <section class="planner" id="planner">
      <div class="planner-inner">
        <h2>Session Planner</h2>
        <p>Build a short roadmap for an initial consult. Your planner creates a consultation agenda and a suggested follow-up cadence. No medical guarantees — educational and supportive.</p>

        <form id="planner-form">
          <label>Client name (optional)
            <input type="text" id="client-name" placeholder="e.g., Jamie" />
          </label>
          <label>Primary focus for sessions
            <select id="focus">
              <option value="sleep">Sleep & rhythms</option>
              <option value="stress">Stress management</option>
              <option value="pain">Chronic pain / mobility</option>
              <option value="gut">Digestion & nutrition</option>
              <option value="mood">Mood & energy</option>
            </select>
          </label>
          <fieldset class="inventory">
            <legend>Whole-person inventory — check areas to include</legend>
            <label><input type="checkbox" value="Sleep" class="area" /> Sleep</label>
            <label><input type="checkbox" value="Stress" class="area" /> Stress & coping</label>
            <label><input type="checkbox" value="Movement" class="area" /> Movement & mobility</label>
            <label><input type="checkbox" value="Nutrition" class="area" /> Nutrition & digestion</label>
            <label><input type="checkbox" value="Mindfulness" class="area" /> Mindfulness & breath</label>
            <label><input type="checkbox" value="Relationships" class="area" /> Relationships & support</label>
            <label><input type="checkbox" value="Work" class="area" /> Work-life balance</label>
            <label><input type="checkbox" value="Environment" class="area" /> Physical environment</label>
          </fieldset>
          <label>Preferred session length
            <select id="sess-length">
              <option value="30">30 minutes</option>
              <option value="45">45 minutes</option>
              <option value="60">60 minutes</option>
            </select>
          </label>

          <div class="form-actions">
            <button type="button" class="btn primary" id="create-plan">Create plan</button>
            <button type="button" class="btn ghost" id="clear-plan">Clear</button>
          </div>
        </form>

        <div id="plan-output" class="plan-output" aria-live="polite">
          <h3>Your plan summary</h3>
          <pre id="plan-text">No plan yet. Click "Create plan."</pre>
          <div class="plan-actions">
            <button id="copy-plan" class="btn">Copy summary</button>
            <button id="download-plan" class="btn">Download .txt</button>
          </div>
        </div>

      </div>
    </section>

    <!-- FAQ -->
    <section class="faq">
      <h2>Questions people ask</h2>
      <details>
        <summary>What can I expect in a first consult?</summary>
        <p>A thorough review of your history, daily rhythms, and current priorities. We collaborate on a practical agenda and a first set of micro-adjustments. This is educational and supportive, not a promise of cure.</p>
      </details>
      <details>
        <summary>Do you take insurance?</summary>
        <p>We provide receipts you can submit to some insurers; contact us for details.</p>
      </details>
      <details>
        <summary>Is this safe with my medical care?</summary>
        <p>We coordinate with your medical team as needed and avoid making diagnostic claims. Always inform your medical provider before changing treatments.</p>
      </details>
    </section>

    <!-- CTA -->
    <section class="cta-strap">
      <h2>Ready to sketch a better rhythm?</h2>
      <p>Request a consult or use the planner above to prepare your agenda.</p>
      <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <strong>{{BUSINESS_NAME}}</strong>
      <address>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
    </div>
    <nav class="foot-nav">
      <a href="privacy.html">Privacy</a>
      <a href="terms.html">Terms</a>
      <a href="sitemap.xml">Sitemap</a>
    </nav>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
