{"path":"assets/css/styles.css","content":"/* Earthy warm theme — no external fonts */
:root{
  --bg:#fbf7f2;--card:#fff;--muted:#6b5a4a;--accent:#a86b3a;--accent-2:#d9b08c;--green:#7aa374;--shadow:0 6px 18px rgba(39,30,22,0.08);
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#2b2b2b;background:var(--bg);}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;max-width:var(--max-width);margin:0 auto}
.brand{display:flex;gap:12px;align-items:center}
.logo{border-radius:8px;background:linear-gradient(180deg,var(--accent-2),var(--accent));padding:6px}
.business{display:block;font-weight:700}
.tag{font-size:0.85rem;color:var(--muted)}
.primary-nav a{margin:0 8px;color:var(--muted);text-decoration:none}
.primary-nav a.active{font-weight:600;color:var(--accent)}
.cta.small{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.main{padding:0}
.hero{position:relative;overflow:hidden;border-radius:12px;margin:18px auto;max-width:var(--max-width);display:flex;align-items:stretch;background:linear-gradient(180deg,#fff8f2,#fff);} 
.hero-inner{padding:48px;flex:1}
.hero h1{margin:0 0 12px;font-size:clamp(1.4rem,2.6vw,2.4rem);color:#2b2b2b}
.hero .intro{margin:0 0 18px;color:var(--muted)}
.hero-actions .btn{margin-right:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;background:var(--card);border:1px solid rgba(0,0,0,0.06);cursor:pointer;text-decoration:none;color:inherit}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid var(--accent-2)}
.btn.large{padding:12px 20px;font-size:1.05rem}
.hero-pattern{width:40%;min-height:200px}
.hero-pattern svg{width:100%;height:100%;opacity:0.18}
.social-proof, .benefits, .process, .planner, .faq, .cta-strap{max-width:var(--max-width);margin:24px auto;padding:22px;background:transparent}
.social-proof h2{margin:0 0 8px}
.testimonials{display:flex;gap:12px;list-style:none;padding:0;margin:12px 0}
.testimonials li{background:var(--card);padding:12px;border-radius:10px;box-shadow:var(--shadow);flex:1}
.benefits .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
.card{background:var(--card);padding:16px;border-radius:10px;box-shadow:var(--shadow)}
.process ol{padding-left:18px}
.planner-inner{display:grid;grid-template-columns:1fr 320px;gap:18px}
#planner-form{background:var(--card);padding:16px;border-radius:10px;box-shadow:var(--shadow)}
#planner-form label{display:block;margin-bottom:10px;font-size:0.95rem}
#planner-form input[type="text"],#planner-form select{width:100%;padding:8px;border-radius:8px;border:1px solid #e8e0da}
.fieldset{border:none}
.inventory{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin:8px 0;padding:6px}
.plan-output{background:var(--card);padding:16px;border-radius:10px;box-shadow:var(--shadow)}
.plan-output pre{white-space:pre-wrap;background:transparent;border:none;margin:0;padding:0}
.plan-actions{display:flex;gap:8px;margin-top:8px}
.faq details{background:var(--card);padding:12px;border-radius:8px;margin-bottom:8px}
.cta-strap{display:flex;align-items:center;justify-content:space-between;gap:12px;background:linear-gradient(90deg,#fff8f2,#fff);padding:20px;border-radius:10px}
.site-footer{max-width:var(--max-width);margin:30px auto;padding:18px;color:var(--muted);display:flex;justify-content:space-between;align-items:center}
.foot-nav a{margin-left:12px;color:var(--muted);text-decoration:none}
@media (max-width:900px){
  .planner-inner{grid-template-columns:1fr}
  .hero{flex-direction:column}
  .hero-pattern{display:none}
  .testimonials{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Session Planner and Whole-Person Inventory
  function el(id){return document.getElementById(id)}
  var createBtn = el('create-plan');
  var clearBtn = el('clear-plan');
  var copyBtn = el('copy-plan');
  var downloadBtn = el('download-plan');
  var planText = el('plan-text');

  function mapAreaNotes(area){
    var map = {
      'Sleep': ['Review bedtime routine','Screening for sleep patterns','Simple wind-down practices'],
      'Stress': ['Identify stress triggers','Breath-based quick tools','Plan for small boundary shifts'],
      'Movement': ['Assess mobility needs','Simple strength/mobility plan','Home practice checklist'],
      'Nutrition': ['Review eating windows','Small swapping ideas','Food journaling prompt'],
      'Mindfulness': ['Short breath practices','Anchor techniques','Micro-meditation prompts'],
      'Relationships': ['Support network review','Communication micro-skills','Referral ideas if needed'],
      'Work': ['Schedule & workload review','Micro-scheduling tips','Pacing and rests plan'],
      'Environment': ['Environmental triggers audit','Declutter or ergonomics steps','Light/noise adjustments']
    };
    return map[area]||['Discuss: '+area];
  }

  function buildAgenda(name, focus, areas, length){
    var lines = [];
    lines.push((name? name+" — ":"") + 'Session plan ('+length+' min)');
    lines.push('Primary focus: '+focus);
    lines.push('');
    lines.push('Consultation agenda:');
    lines.push('- Brief history & priorities (10-20% of session)');
    if(areas.length){
      areas.forEach(function(a){
        var notes = mapAreaNotes(a);
        lines.push('- '+a+': '+notes[0]);
      });
    } else {
      lines.push('- Open exploration to identify priority areas');
    }
    lines.push('');
    lines.push('Suggested follow-up cadence:');

    // Build cadence suggestions based on number of areas
    if(areas.length >=5){
      lines.push('- Intensive first month: weekly 30–45 min check-ins for 4 weeks, then biweekly review');
    } else if(areas.length >=3){
      lines.push('- Moderate track: two check-ins in the first month (weeks 2 and 4), then monthly');
    } else if(areas.length >=1){
      lines.push('- Light track: single follow-up in 2–3 weeks, then adjust as needed');
    } else {
      lines.push('- Initial check-in in 2–3 weeks to set direction');
    }

    lines.push('');
    lines.push('Practical micro-goals (examples):');
    if(areas.length){
      areas.slice(0,4).forEach(function(a,i){
        var notes = mapAreaNotes(a);
        lines.push((i+1)+'. '+notes[1]+' — try for 7–14 days');
      });
    } else {
      lines.push('1. Track one habit for 7 days (sleep, food, or stress)');
    }

    lines.push('');
    lines.push('Notes: This plan is educational and supportive. It is not a medical diagnosis or promise of cure. Coordinate with your healthcare providers when relevant.');

    return lines.join('\n');
  }

  function getCheckedAreas(){
    var checks = Array.prototype.slice.call(document.querySelectorAll('.area:checked'));
    return checks.map(function(c){return c.value});
  }

  createBtn.addEventListener('click', function(){
    var name = el('client-name').value.trim();
    var focus = el('focus').value;
    var length = el('sess-length').value;
    var areas = getCheckedAreas();
    var text = buildAgenda(name, focus, areas, length);
    planText.textContent = text;
  });

  clearBtn.addEventListener('click', function(){
    document.getElementById('planner-form').reset();
    planText.textContent = 'No plan yet. Click "Create plan."';
  });

  copyBtn.addEventListener('click', function(){
    var text = planText.textContent;
    if(!navigator.clipboard){
      // fallback
      var ta = document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}ta.remove();
      alert('Plan copied to clipboard');
      return;
    }
    navigator.clipboard.writeText(text).then(function(){
      copyBtn.textContent = 'Copied';
      setTimeout(function(){copyBtn.textContent='Copy summary'},1500);
    },function(){alert('Unable to copy.');});
  });

  downloadBtn.addEventListener('click', function(){
    var text = planText.textContent || '';
    var blob = new Blob([text],{type:'text/plain;charset=utf-8'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  });

  // Accessibility: allow Enter to submit when focused on form
  document.getElementById('planner-form').addEventListener('submit', function(e){e.preventDefault();createBtn.click();});

})();
"} 
